16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "bulk_signup_warning")
67	    private Boolean bulkSignupWarning;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public LocalDate getRegistrationDate() {
108	        return this.registrationDate;
109	    }
110	
111	    public void setRegistrationDate(LocalDate registrationDate) {
112	        this.registrationDate = registrationDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    public void setCustomerCode(String customerCode) {
120	        this.customerCode = customerCode;
121	    }
122	
123	    public String getHouseholdId() {
124	        return this.householdId;
125	    }
126	
127	    public void setHouseholdId(String householdId) {
128	        this.householdId = householdId;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    public Boolean getBulkSignupWarning() {
140	        return this.bulkSignupWarning;
141	    }
142	
143	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
144	        this.bulkSignupWarning = bulkSignupWarning;
145	    }
146	
147	    public Integer getHouseholdSize() {
148	        return this.householdSize;
149	    }
150	
151	    public void setHouseholdSize(Integer householdSize) {
152	        this.householdSize = householdSize;
153	    }
154	
155	    /**
156	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
157	     * is the last two digits of the registration date's year (e.g. {@code "SMI-0007-M26"}).
158	     * Derived from the owner's own fields, so it stays consistent with them.
159	     */
160	    @Transient
161	    public String getMembershipNumber() {
162	        if (this.customerCode == null || this.registrationDate == null) {
163	            return null;
164	        }
165	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
166	    }
167	
168	    /**
169	     * The owner's membership level, a number from 1 to 3. Every owner starts at level 1;
170	     * one level is added when an email is on file and one more when the owner is unique
171	     * (namesake count of zero). The level is capped at 3, leaving level 4 reserved for
172	     * tenure. Derived from the owner's own fields, so it stays consistent with them.
173	     */
174	    @Transient
175	    public Integer getMembershipLevel() {
176	        int level = 1;
177	        boolean hasEmail = this.email != null && !this.email.isEmpty();
178	        if (hasEmail) {
179	            level++;
180	        }
181	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
182	        if (unique) {
183	            level++;
184	        }
185	        return Math.min(level, 3);
186	    }
187	
188	    /**
189	     * The owner's locality: the canonical region derived from the city via the fixed
190	     * {@link CityRegionTable}, or {@code "UNKNOWN"} when the city is not in the table.
191	     * Derived from the owner's own city, so it stays consistent with it.
192	     */
193	    @Transient
194	    public String getLocality() {
195	        return CityRegionTable.regionFor(this.city);
196	    }
197	
198	    /**
199	     * Normalize the registration date before persisting: default it to the server's
200	     * current date when none was supplied, then roll it forward onto a business day so
201	     * every newly persisted owner is registered on a weekday.
202	     */
203	    @PrePersist
204	    void normalizeRegistrationDate() {
205	        if (this.registrationDate == null) {
206	            this.registrationDate = LocalDate.now();
207	        }
208	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
209	    }
210	
211	    protected Set<Pet> getPetsInternal() {
212	        if (this.pets == null) {
213	            this.pets = new HashSet<>();
214	        }
215	        return this.pets;
216	    }
217	
218	    protected void setPetsInternal(Set<Pet> pets) {
219	        this.pets = pets;
220	    }
221	
222	    public List<Pet> getPets() {
223	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
224	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
225	        return Collections.unmodifiableList(sortedPets);
226	    }
227	
228	    public void setPets(List<Pet> pets) {
229	        this.pets = new HashSet<>(pets);
230	    }
231	
232	    public void addPet(Pet pet) {
233	        getPetsInternal().add(pet);
234	        pet.setOwner(this);
235	    }
236	
237	    /**
238	     * Return the Pet with the given name, or null if none found for this Owner.
239	     *
240	     * @param name to test
241	     * @return true if pet name is already in use
242	     */
243	    public Pet getPet(String name) {
244	        return getPet(name, false);
245	    }
246	
247	    /**
248	     * Return the Pet with the given name, or null if none found for this Owner.
249	     *
250	     * @param name to test
251	     * @return true if pet name is already in use
252	     */
253	    public Pet getPet(String name, boolean ignoreNew) {
254	        name = name.toLowerCase();
255	        for (Pet pet : getPetsInternal()) {
256	            if (!ignoreNew || !pet.isNew()) {
257	                String compName = pet.getName();
258	                compName = compName.toLowerCase();
259	                if (compName.equals(name)) {
260	                    return pet;
261	                }
262	            }
263	        }
264	        return null;
265	    }
266	
267	    public Pet getPet(Integer petId) {
268	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
269	    }
270	
271	    @Override
272	    public String toString() {
273	        return new ToStringCreator(this)
274	
275	            .append("id", this.getId())
276	            .append("new", this.isNew())
277	            .append("lastName", this.getLastName())
278	            .append("firstName", this.getFirstName())
279	            .append("address", this.address)
280	            .append("city", this.city)
281	            .append("telephone", this.telephone)
282	            .toString();
283	    }
284	}
