24	/**
25	 * Simple JavaBean domain object representing an person.
26	 *
27	 * @author Ken Krebs
28	 */
29	@MappedSuperclass
30	public class Person extends BaseEntity {
31	
32	    @Column(name = "first_name")
33	    @NotEmpty
34	    protected String firstName;
35	
36	    @Column(name = "last_name")
37	    @NotEmpty
38	    protected String lastName;
39	
40	    public String getFirstName() {
41	        return this.firstName;
42	    }
43	
44	    public void setFirstName(String firstName) {
45	        this.firstName = firstName;
46	    }
47	
48	    public String getLastName() {
49	        return this.lastName;
50	    }
51	
52	    public void setLastName(String lastName) {
53	        this.lastName = lastName;
54	    }
55	
56	    /**
57	     * The upper-cased first letters of the first and last name, dot-separated
58	     * with a trailing dot (e.g. {@code "J.S."}).
59	     */
60	    @Transient
61	    public String getInitials() {
62	        return Character.toUpperCase(this.firstName.charAt(0)) + "."
63	            + Character.toUpperCase(this.lastName.charAt(0)) + ".";
64	    }
65	
66	}
