262	    /**
263	     * Size of the household this new owner will belong to once persisted: the owners
264	     * already sharing its household id, plus the owner itself. An owner with no shared
265	     * household id stands alone, so its household size is one.
266	     */
267	    private int householdSizeIncluding(Owner owner) {
268	        if (owner.getHouseholdId() == null) {
269	            return 1;
270	        }
271	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
272	    }
273	
274	    /**
275	     * Count the existing owners that already share the given first and last name,
276	     * compared case-insensitively. Used to stamp a new owner's namesake count at
277	     * registration, before it is itself persisted.
278	     */
279	    private int countNamesakes(String firstName, String lastName) {
280	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
281	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
282	            .count();
283	    }
