315	    @Override
316	    @Transactional
317	    public String shareHousehold(Owner owner) throws DataAccessException {
318	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
319	        // Backfill the existing members so the whole household carries one shared id.
320	        householdMembers(owner.getLastName(), owner.getAddress()).stream()
321	            .filter(member -> !householdId.equals(member.getHouseholdId()))
322	            .forEach(member -> {
323	                member.setHouseholdId(householdId);
324	                ownerRepository.save(member);
325	            });
326	        owner.setHouseholdId(householdId);
327	        return householdId;
328	    }
329	
330	    /**
331	     * Return the existing owners that already occupy the household identified by the
332	     * given last name and address, i.e. that map to the same shared household id.
333	     */
334	    private List<Owner> householdMembers(String lastName, String address) {
335	        String householdId = householdIdGenerator.generate(lastName, address);
336	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
337	            .filter(owner -> householdId.equals(
338	                householdIdGenerator.generate(owner.getLastName(), owner.getAddress())))
339	            .toList();
340	    }
