354	    private <T> T findEntityById(Supplier<T> supplier) {
355	        try {
356	            return supplier.get();
357	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
358	            // Just ignore not found exceptions for Jdbc/Jpa realization
359	            return null;
360	        }
361	    }
