62	
63	    /**
64	     * Maximum number of owners allowed to be registered in a single city. A new owner
65	     * whose city already holds this many owners is rejected as a conflict.
66	     */
67	    private static final long MAX_OWNERS_PER_CITY = 50;
68	
69	    /**
70	     * Maximum number of owners allowed to be registered in a single day. Once this many
71	     * owners already carry today's registration date, a further create is rejected as
72	     * too many requests.
73	     */
74	    private static final long MAX_OWNERS_PER_DAY = 100;
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    private final TelephoneNormalizer telephoneNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final OwnerAuditLogger ownerAuditLogger;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 TelephoneNormalizer telephoneNormalizer,
97	                                 EmailNormalizer emailNormalizer,
98	                                 AddressNormalizer addressNormalizer,
99	                                 OwnerAuditLogger ownerAuditLogger) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.petMapper = petMapper;
103	        this.visitMapper = visitMapper;
