135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        String address = addressNormalizer.normalize(owner.getAddress());
141	        if (addressNormalizer.isBlank(address)) {
142	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
143	        }
144	        owner.setAddress(address);
145	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
146	        if (e164Telephone.isEmpty()) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        String telephone = e164Telephone.get();
150	        String email = emailNormalizer.normalize(owner.getEmail());
151	        if (email != null && !emailNormalizer.isValid(email)) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        LocalDate registrationDate = BusinessDay.rollForward(
155	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate());
156	        owner.setRegistrationDate(registrationDate);
157	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
158	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
159	        }
160	        if (clinicService.existsOwnerByTelephone(telephone)) {
161	            return new ResponseEntity<>(HttpStatus.CONFLICT);
162	        }
163	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
164	            return new ResponseEntity<>(HttpStatus.CONFLICT);
165	        }
166	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
167	        if (!sharesHousehold
168	            && clinicService.existsOwnerByLastNameAndAddress(owner.getLastName(), owner.getAddress())) {
169	            return new ResponseEntity<>(HttpStatus.CONFLICT);
170	        }
171	        owner.setTelephone(telephone);
172	        owner.setEmail(email);
173	        if (sharesHousehold) {
174	            clinicService.shareHousehold(owner);
175	        }
176	        this.clinicService.saveOwner(owner);
177	        this.ownerAuditLogger.logCreated(owner);
178	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
192	        if (e164Telephone.isEmpty()) {
193	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
194	        }
195	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
196	        if (email != null && !emailNormalizer.isValid(email)) {
197	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
198	        }
199	        currentOwner.setAddress(ownerFieldsDto.getAddress());
200	        currentOwner.setCity(ownerFieldsDto.getCity());
201	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
202	        currentOwner.setLastName(ownerFieldsDto.getLastName());
203	        currentOwner.setTelephone(e164Telephone.get());
204	        currentOwner.setEmail(email);
205	        this.clinicService.saveOwner(currentOwner);
206	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
207	    }
